package com.example.statusdrafter.controller; import com.example.statusdrafter.entity.*; import com.example.statusdrafter.service.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@Controller @RequestMapping("/manager") public class ManagerController {final UserService users;final TaskService tasks;final StatusUpdateService statuses;final ReportService reports;final NotificationService notifications;public ManagerController(UserService u,TaskService t,StatusUpdateService s,ReportService r,NotificationService n){users=u;tasks=t;statuses=s;reports=r;notifications=n;} User me(Authentication a){return users.byUsername(a.getName());}
@GetMapping("/dashboard")String dashboard(Model m){Map<String,Long> r=reports.overall();m.addAttribute("report",r);m.addAttribute("progress",reports.percent(r));m.addAttribute("employees",users.employees());m.addAttribute("overdue",tasks.overdueAll());return "manager/dashboard";}
@GetMapping("/employees")String employees(Model m){m.addAttribute("employees",users.employees());return "manager/employees";}
@GetMapping("/employee-tasks")String employeeTasks(@RequestParam(required=false)Long employeeId,Model m){User e=employeeId==null?null:users.all().stream().filter(x->x.getId().equals(employeeId)).findFirst().orElseThrow();m.addAttribute("employees",users.employees());m.addAttribute("selected",employeeId);m.addAttribute("tasks",employeeId==null?tasks.search(null,null,null,null,null,null,null):tasks.mine(e));return "manager/employee-tasks";}
@GetMapping("/status-updates")String updates(@RequestParam(required=false)Long employeeId,Model m){m.addAttribute("employees",users.employees());if(employeeId!=null){User e=users.all().stream().filter(x->x.getId().equals(employeeId)).findFirst().orElseThrow();m.addAttribute("updates",statuses.mine(e));}else{List<StatusUpdate> all=new ArrayList<>();users.employees().forEach(e->all.addAll(statuses.mine(e)));all.sort(Comparator.comparing(StatusUpdate::getUpdateDate).reversed());m.addAttribute("updates",all);}return "manager/status-updates";}
@GetMapping("/reports")String report(Model m){Map<String,Long> r=reports.overall();m.addAttribute("report",r);m.addAttribute("progress",reports.percent(r));return "manager/reports";} @GetMapping("/deadlines")String deadlines(Model m){m.addAttribute("overdue",tasks.overdueAll());return "manager/deadlines";}
}
